with latest as (select *, row_number() over (partition by store_id order by quantity desc nulls last, id) as rank_in_group from inventory qualify rank_in_group = 1) select date_trunc('year', last_restock) as year_start, case when quantity >= 197 then 'PREMIUM' else 'STANDARD' end as quantity_tier, product_id, max(quantity) as max_quantity, round(avg(quantity), 2) as avg_quantity from latest group by date_trunc('year', last_restock), case when quantity >= 197 then 'PREMIUM' else 'STANDARD' end, product_id order by product_id desc nulls last;
